def get_leads(): return DB["leads"]
@app.post("/api/leadforms")
def create_form(f: LeadForm):
    d=f.dict(); d["id"]=str(uuid.uuid4())[:8]; DB["leads"].append(d); return d
@app.post("/api/auth/signup")
def signup(u: UserCreate):
    # تشفير - بنخزن التشفير بس - ما بنخزن كلمة السر الحقيقية
    for ex in DB["users"]:
        if ex["email"]==u.email: return {"error":"الايميل ده مسجل قبل كده - اعمل دخول - او استخدم ايميل تاني - انت البتختار"}
    # u.password هنا هو التشفير اللي جاي من المتصفح - بنخزنو زي ما هو - ما بنفكو
    d={"id":str(uuid.uuid4())[:8],"name":u.name,"email":u.email,"password_hash":u.password,"role":u.role,"created_at":str(datetime.datetime.now())}
    DB["users"].append(d)
    # بنرجع الاسم والايميل والدور بس - ما بنرجع كلمة السر - ولا التشفير
    return {"user":{"id":d["id"],"name":d["name"],"email":d["email"],"role":d["role"]}}
@app.post("/api/auth/login")
def login(data: dict):
    pw_hash=data.get("password_hash",""); email=data.get("email","")
    for u in DB["users"]:
        if u["email"]==email and u["password_hash"]==pw_hash:
            return {"user":{"id":u["id"],"name":u["name"],"email":u["email"],"role":u["role"]}}
    return {"error":"الايميل او كلمة السر غلط"}
