def list_ads():
    # بنرجع الاعلانات من غير اي بيانات شخصية حساسة - بس الاسم والاعلان
    return [{"id":a["id"],"name":a["name"],"format":a["format"],"status":a["status"],"headline":a.get("headline",""),"primary_text":a.get("primary_text",""),"cta":a.get("cta",""),"placement":a.get("placement",""),"advertiser":a.get("advertiser","")} for a in DB["ads"]]
