@app.post("/api/ads/{ad_id}/approve")
def approve(ad_id: str):
    for a in DB["ads"]:
        if a["id"]==ad_id: a["status"]="LIVE"
    return {"ok":True}
@app.get("/api/feed")
def feed(placement: str=""):
    # ده هو API المنصات التانية - NoorSocial / NoorShot / NoorChat / NoorMarket - بتشيل من هنا الاعلانات Live - حقيقة - جوة مشروعك الخاص
    live=[a for a in DB["ads"] if a["status"]=="LIVE"]
    if placement:
        live=[a for a in live if placement in str(a.get("placements",[])) or placement in str(a.get("placement",""))]
    # بنرجع الاعلان بس - من غير بيانات شخصية
    return [{"id":a["id"],"name":a["name"],"headline":a.get("headline",""),"primary_text":a.get("primary_text",""),"cta":a.get("cta",""),"image_url":a.get("image_url",""),"placement":a.get("placement",""),"advertiser":a.get("advertiser",""),"objective":a.get("objective","")} for a in live]
