def track_click(ad_id: str=""):
    DB["analytics"]["clicks"]+=1; return {"ok":True}
@app.post("/api/track/purchase")
def track_purchase(ad_id: str=""):
    DB["analytics"]["purchases"]+=1; DB["analytics"]["sales"]+=1; return {"ok":True}
